// Bridge to the PodLens Racket engine (glaze adapter, #63).
//
// Production carrier: glaze's loopback HTTP adapter with a per-launch
// token. run-app opens the page with ?glaze-token=… which the server
// exchanges for an HttpOnly glaze_token cookie — every same-origin
// request (RPC fetch, SSE, and the <audio> media stream) carries it
// automatically. The native GLZ1 carrier (window.__glz1) remains
// available for development; media streaming needs the HTTP origin.
//
// Every call is a typed RPC from rivet-schema.json (src/rpc.ts,
// generated by scripts/gen-rpc-types.py). The backend converts camelCase
// JSON DTOs to the schema's field-ordered RVT1 wire values.

interface Glz1 {
  invoke(
    path: string,
    args?: unknown,
    opts?: { method?: string; timeoutMs?: number },
  ): Promise<unknown>;
  on?(name: string, fn: (payload: unknown) => void): void;
}

declare global {
  interface Window {
    __glz1?: Glz1;
  }
}

function nativeBridge(): Glz1 | null {
  return (typeof window !== 'undefined' && window.__glz1) || null;
}

let probe: Promise<boolean> | null = null;

/** True once a backend answers — native bridge present, or /api/health ok. */
export function hasBackend(): Promise<boolean> {
  if (!probe) {
    const g = nativeBridge();
    probe = g
      ? Promise.resolve(true)
      : fetch('/api/health', { method: 'POST' })
          .then((r) => r.ok)
          .catch(() => false);
  }
  return probe;
}

/** POST JSON to the backend; returns the parsed response.
 *  Always same-origin fetch: the native bridge invoke channel wedges on
 *  macOS CI hosts once media playback starts (podlens#63), while the host
 *  HTTP server answers fetch reliably on every platform. */
export async function apiPost<T>(path: string, body?: unknown): Promise<T> {
  return apiPostFetch<T>(path, body);
}

/** Fetch-only POST: bypasses the native bridge invoke channel, which wedges
 *  on macOS CI hosts once media playback starts (podlens#63). */
export async function apiPostFetch<T>(path: string, body?: unknown): Promise<T> {
  const res = await fetch(path, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body ?? {}),
  });
  if (!res.ok) {
    const detail = await res.text();
    // glaze's typed error body carries the engine's user-facing message
    // (bad-param channel); fall back to raw text for transport errors.
    let message = detail.slice(0, 400) || `${path} failed: ${res.status}`;
    try {
      const body = JSON.parse(detail) as { error?: unknown; message?: unknown };
      const m = typeof body.error === 'string' ? body.error : typeof body.message === 'string' ? body.message : null;
      if (m) message = m;
    } catch { /* non-JSON body */ }
    throw new Error(message);
  }
  return (await res.json()) as T;
}

/**
 * Engine push channel, by event name (notify / job-progress /
 * episodes-changed / open-url / update-available). HTTP carrier: SSE
 * /glaze/events. Native carrier: __glz1.on. Degrades silently where
 * neither is available — never breaks the page.
 */
export function onEngineEvent(name: string, cb: (payload: unknown) => void): () => void {
  const g = nativeBridge();
  if (g && typeof g.on === 'function') {
    g.on(name, cb);
    return () => {};
  }
  try {
    const es = new EventSource('/glaze/events');
    const handler = (e: MessageEvent) => {
      try {
        cb(JSON.parse(e.data));
      } catch {
        cb(e.data);
      }
    };
    es.addEventListener(name, handler);
    return () => es.close();
  } catch {
    return () => {};
  }
}

/**
 * Media source for the webview's <audio> element: the host streams the
 * engine's audio cache with Range support on the same origin; the
 * bootstrap cookie authenticates the request. Seeking (sentence jumps,
 * −15/+30) rides HTTP 206 partial content.
 */
export function audioUrl(id: string): string {
  return `/api/audio/${encodeURIComponent(id)}`;
}